trim.if:
select case when wtpd.trade_id is not null then '04' else '' end paymentStatus, /*缴款状态*/ bobp.ENTRUST_ID entrustId, /*委托编号*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ fp.FINPROD_MARKET_ID finprodMarketId, /*资产代码*/ fp.finprod_name finprodName, /*资产名称*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_DATE payDate, /*缴款日*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE = wtp.YIELD
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= to_date(#{startDate}, 'yyyy-MM-dd')
and bo.BID_DATE <= to_date(#{endDate}, 'yyyy-MM-dd')
AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in
#{currTradeMarket}

union all select bo.PAY_TYPE paymentStatus, /*缴款状态*/ bobp.ENTRUST_ID entrustId, /*委托编号*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ fp.FINPROD_MARKET_ID finprodMarketId, /*资产代码*/ fp.finprod_name finprodName, /*资产名称*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_DATE payDate, /*缴款日*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.TRADE_ID is null AND BOBP.WIN_PRICE IS NOT NULL
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= to_date(#{startDate}, 'yyyy-MM-dd')
and bo.BID_DATE <= to_date(#{endDate}, 'yyyy-MM-dd')
and bo.PAY_TYPE = #{paymentStatus}
AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in
#{currTradeMarket}
minus select bo.PAY_TYPE paymentStatus, /*缴款状态*/ bobp.ENTRUST_ID entrustId, /*委托编号*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ fp.FINPROD_MARKET_ID finprodMarketId, /*资产代码*/ fp.finprod_name finprodName, /*资产名称*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_DATE payDate, /*缴款日*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE = wtp.YIELD
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= to_date(#{startDate}, 'yyyy-MM-dd')
and bo.BID_DATE <= to_date(#{endDate}, 'yyyy-MM-dd')
AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in
#{currTradeMarket}

union all select case when bobp.trade_id is not null then '05' else '' end paymentStatus, /*缴款状态*/ bobp.ENTRUST_ID entrustId, /*委托编号*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ fp.FINPROD_MARKET_ID finprodMarketId, /*资产代码*/ fp.finprod_name finprodName, /*资产名称*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_DATE payDate, /*缴款日*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE
where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win AND bobp.trade_id is not NULL
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= to_date(#{startDate}, 'yyyy-MM-dd')
and bo.BID_DATE <= to_date(#{endDate}, 'yyyy-MM-dd')
AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in
#{currTradeMarket}
